  for r in
    select * from (values
      ('pack3-costco-rotisserie-chicken', 'easy', 'everyday-products', 'How much is a rotisserie chicken at Costco?', 'The whole rotisserie chicken at a U.S. Costco warehouse, 2026.', '/items/rotisserie-chicken.svg', 'Illustration of a golden rotisserie chicken in a clear plastic container', 4.99, 'Costco U.S. warehouse price', '2026-06-24', 'Costco has sold its rotisserie chicken for $4.99 since it was introduced in 1994. The only time it went up ($5.99) was during the Great Recession.', 'The One And Only Time Costco Raised Its Rotisserie Chicken Price', 'Tasting Table', 'https://www.tastingtable.com/2198157/costco-rotisserie-chicken-raised-price-recession/', 'It has been consistently priced at $4.99 since it was first put on the shelves in 1994.', ''),
      ('pack3-spotify-premium', 'easy', 'entertainment', 'How much is Spotify Premium (Individual) per month in the U.S.?', 'The Individual plan, monthly price after Spotify''s January 2026 increase.', '/items/music-stream.svg', 'Illustration of headphones around a phone playing music', 12.99, 'Spotify U.S. monthly price, Premium Individual', '2026-01-15', 'Spotify raised its U.S. Premium Individual plan from $11.99 to $12.99 a month in January 2026.', 'Spotify announces price hikes across all major plans in the US', 'Notebookcheck', 'https://www.notebookcheck.net/Spotify-announces-price-hikes-across-all-major-plans-in-the-US.1205251.0.html', 'The Individual Premium plan now costs $12.99 per month, up from $11.99.', 'Confirm on spotify.com/premium before verifying.'),
      ('pack3-airtag-2', 'easy', 'technology', 'How much does one Apple AirTag (2nd generation) cost?', 'A single AirTag 2 at Apple''s regular U.S. price, not a sale.', '/items/tracker-tag.svg', 'Illustration of a round white item tracker on a key ring with a map pin', 29.00, 'Apple''s U.S. retail price, single AirTag 2', '2026-08-18', 'A single AirTag 2 costs $29 at Apple. A 4-pack is $99, and stores often discount it.', 'AirTag 2 Drops to Low Price of $89 for 4-Pack', 'MacRumors', 'https://www.macrumors.com/2026/08/18/airtag-2-89-for-4-pack/', 'available for $24.00, down from $29.00', 'Confirm on apple.com/airtag before verifying.'),
      ('pack3-powerball-ticket', 'easy', 'personal-finance', 'How much does one Powerball lottery play cost?', 'A single standard Powerball play, without the Power Play add-on.', '/items/lottery-ticket.svg', 'Illustration of a lottery ticket with five white numbers and one red number', 2.00, 'Price of one Powerball play', '2025-12-23', 'Each Powerball play costs $2. Adding Power Play, which multiplies non-jackpot prizes, costs $1 more.', 'How much does a Powerball lottery ticket cost?', 'FOX 5 New York', 'https://www.fox5ny.com/news/how-much-does-powerball-lottery-ticket-cost-2025', 'A Powerball ticket costs $2 per play.', ''),
      ('pack3-xbox-series-x', 'easy', 'technology', 'How much does an Xbox Series X cost in the U.S. right now?', 'The standard 1TB Xbox Series X with a disc drive, Microsoft''s U.S. price since August 1, 2026.', '/items/console-tower.svg', 'Illustration of a tall black game console next to a controller', 799.99, 'Microsoft''s U.S. retail price, Xbox Series X 1TB', '2026-08-01', 'Microsoft raised the Xbox Series X to $799.99 in the U.S. on August 1, 2026, its second increase in a year. It launched at $499 in 2020.', 'Here''s A Breakdown Of The New Prices For Xbox Series X|S Consoles As Of August 2026', 'Pure Xbox', 'https://www.purexbox.com/news/2026/08/heres-a-breakdown-of-the-new-prices-for-xbox-series-xs-consoles-as-of-august-2026', 'Xbox Series X (1TB, Disc) | £669.99 | $799.99', 'Confirm on xbox.com before verifying.'),
      ('pack3-galaxy-z-fold-8', 'medium', 'technology', 'What is the starting price of the Samsung Galaxy Z Fold 8?', 'Samsung''s U.S. starting price for the base model (256GB) at its 2026 launch.', '/items/foldable-phone.svg', 'Illustration of a foldable phone opened like a book', 1899.00, 'Samsung''s U.S. starting retail price', '2026-07-22', 'Samsung announced the Galaxy Z Fold 8 on July 22, 2026, starting at $1,899 in the U.S. for the 12GB + 256GB model.', 'Samsung confirms Galaxy Z Fold 8 price starts at $1,899', 'SamMobile', 'https://www.sammobile.com/news/samsung-confirms-galaxy-z-fold-8-price-starts-at-1899/', 'Pricing starts at $1,899 in the United States for the 12GB + 256GB model.', ''),
      ('pack3-honda-civic-2027', 'medium', 'everyday-products', 'What is the starting price of a 2027 Honda Civic?', 'The base Civic Sedan LX, manufacturer''s suggested retail price before the destination fee.', '/items/compact-car.svg', 'Illustration of a white compact sedan', 24995.00, 'Starting MSRP of the 2027 Civic Sedan LX, excluding destination', '2026-10-08', 'The 2027 Honda Civic Sedan LX starts at $24,995 before a $1,295 destination charge.', '2027 Honda Civic Arrives at Dealers with New Sport-L Trim', 'AutoGuide', 'https://www.autoguide.com/auto/manufacturers/honda/2027-honda-civic-arrives-at-dealers-with-new-sport-l-trim-44639983', 'All MSRP figures exclude a $1,295 destination and handling charge.', 'Confirm on automobiles.honda.com before verifying.'),
      ('pack3-cobain-cardigan', 'medium', 'entertainment', 'How much did Kurt Cobain''s cardigan from Nirvana''s MTV Unplugged show sell for at auction?', 'The olive-green sweater he wore at the 1993 concert, sold by Julien''s Auctions in October 2019.', '/items/cardigan.svg', 'Illustration of a worn olive-green button-up cardigan', 334000.00, 'Final auction price', '2019-10-26', 'Julien''s Auctions sold Cobain''s unwashed MTV Unplugged cardigan for $334,000 in October 2019, a record for a sweater at the time.', 'Kurt Cobain''s ''Unplugged'' Sweater Sells for Record $334,000 at Auction', 'Rolling Stone', 'https://www.rollingstone.com/music/music-news/kurt-cobain-unplugged-sweater-sells-334000-auction-904246/', 'Kurt Cobain''s famed green cardigan from Nirvana''s MTV Unplugged concert sold for $334,000 at auction Saturday', ''),
      ('pack3-titanic-door', 'medium', 'entertainment', 'How much did the floating ''door'' from the movie Titanic sell for at auction?', 'The wooden panel Rose floats on at the end of the 1997 film, sold by Heritage Auctions in March 2024.', '/items/floating-door.svg', 'Illustration of a wooden panel floating on dark ocean water at night', 718750.00, 'Final auction price', '2024-03-23', 'Heritage Auctions sold the Titanic ''door'', actually part of a door frame, for $718,750 on March 23, 2024.', 'Controversial ''Titanic'' Door Sells at Auction', 'Smithsonian Magazine', 'https://www.smithsonianmag.com/smart-news/controversial-titanic-door-sells-at-auction-180984050/', 'the floating wooden panel from Titanic—has sold at auction for $718,750.', ''),
      ('pack3-thriller-jacket', 'medium', 'luxury-goods', 'How much did Michael Jackson''s jacket from the ''Thriller'' music video sell for at auction?', 'The red-and-black leather jacket he wore in the 1983 video, sold by Julien''s Auctions in June 2011.', '/items/leather-jacket.svg', 'Illustration of a red leather jacket with black stripes', 1800000.00, 'Final auction price', '2011-06-26', 'The Thriller jacket sold for $1.8 million at Julien''s Auctions in Beverly Hills in June 2011.', 'Michael Jackson''s ''Thriller'' jacket sells for $1.8M at auction', 'ABC7 Chicago', 'https://abc7chicago.com/archive/8215503', 'Michael Jackson''s ''Thriller'' jacket sells for $1.8M at auction', ''),
      ('pack3-pikachu-illustrator', 'hard', 'entertainment', 'How much did Logan Paul''s Pikachu Illustrator Pokémon card sell for at auction?', 'The PSA 10 card sold by Goldin in February 2026, final price including the buyer''s premium.', '/items/trading-card.svg', 'Illustration of a yellow trading card in a clear graded case', 16492000.00, 'Final auction price including buyer''s premium', '2026-02-16', 'Goldin sold the Pikachu Illustrator card for $16,492,000 on February 16, 2026 ($13.3 million plus fees), the most ever paid for a trading card.', 'Logan Paul''s rare Pokemon card becomes most expensive ever sold in record-setting auction', 'Guinness World Records', 'https://www.guinnessworldrecords.com/news/2026/2/logan-pauls-rare-pokemon-card-becomes-most-expensive-ever-sold-in-record-setting-auction', 'sold for $16,492,000 ... including the buyer''s premium', ''),
      ('pack3-babe-ruth-called-shot-jersey', 'hard', 'sports', 'How much did Babe Ruth''s ''called shot'' jersey sell for at auction?', 'The Yankees jersey he wore in the 1932 World Series, sold by Heritage Auctions in August 2024.', '/items/baseball-jersey.svg', 'Illustration of a white pinstriped baseball jersey with the number 3', 24120000.00, 'Final auction price', '2024-08-25', 'Heritage Auctions sold the jersey Ruth wore when he ''called his shot'' in the 1932 World Series for $24.12 million, a record for any sports collectible.', 'Babe Ruth''s ''called shot'' jersey sells at auction for over $24 million', 'ABC News (Associated Press)', 'https://abcnews.go.com/US/wireStory/babe-ruths-called-shot-jersey-sells-auction-24-113135391', 'Heritage Auctions said the New York Yankee slugger''s jersey went for a record-breaking $24.12 million', ''),
      ('pack3-t-rex-stan', 'hard', 'science-and-infrastructure', 'How much did ''Stan'', a Tyrannosaurus rex skeleton, sell for at auction?', 'One of the most complete T. rex skeletons ever found, sold by Christie''s in New York in October 2020.', '/items/dinosaur-skeleton.svg', 'Illustration of a Tyrannosaurus rex skeleton on a museum stand', 31800000.00, 'Final auction price', '2020-10-06', 'Christie''s sold Stan for $31.8 million on October 6, 2020, nearly four times its estimate. It is now headed to a natural history museum in Abu Dhabi.', 'Stan the Tyrannosaurus rex sold at auction; paleontologists are furious', 'National Geographic', 'https://www.nationalgeographic.com/science/article/stan-tyrannosaurus-rex-sold-at-auction-paleontologists-are-furious', 'On October 6, the London-based auction house Christie''s sold the T. rex for a record $31.8 million', ''),
      ('pack3-griffin-penthouse', 'hard', 'real-estate', 'How much did billionaire Ken Griffin pay for his New York penthouse, the most expensive home ever sold in the U.S. at the time?', 'The penthouse at 220 Central Park South, closed in January 2019.', '/items/penthouse-tower.svg', 'Illustration of a tall limestone apartment tower beside a park', 238000000.00, 'Purchase price', '2019-01-23', 'Ken Griffin paid about $238 million for the penthouse in 2019, the most ever paid for a home in the United States at the time.', 'Billionaire Ken Griffin Buys the Most Expensive Home Ever Sold in the US', 'NBC New York', 'https://www.nbcnewyork.com/news/national-international/Billionaire-Ken-Griffin-Buys-the-Most-Expensive-Home-Ever-Sold-in-the-US-504764651.html', 'paying around $238 million for a New York penthouse overlooking Central Park', 'Reported as ''around $238 million''; the commonly cited figure is $238 million.'),
      ('pack3-instagram-acquisition', 'hard', 'business-and-markets', 'How much did Facebook pay to buy Instagram in 2012?', 'The price Facebook agreed to pay, in cash and stock, when it announced the deal in April 2012.', '/items/photo-app.svg', 'Illustration of a camera surrounded by printed photos', 1000000000.00, 'Announced purchase price', '2012-04-09', 'Facebook agreed to buy Instagram for $1 billion in cash and stock on April 9, 2012, when the app had about 13 employees.', 'Facebook acquires Instagram for $1 billion', 'FOX 13 (CNN)', 'https://www.fox13now.com/2012/04/09/facebook-acquires-instagram-for-1-billion', 'Facebook has agreed to buy photo sharing network Instagram for $1 billion in a combination of cash and stock', 'Because of Facebook''s stock price, the deal was worth about $715 million when it closed; the question asks for the agreed price.')
    ) as t(slug, difficulty, cat, prompt, context, image, image_alt, amount, definition, ref_date, explanation,
           src_title, src_publisher, src_url, src_excerpt, src_notes)
  loop
    insert into public.questions (slug, prompt, context, difficulty, category_id, image_url, image_alt, image_credit, status, is_sample)
    values (r.slug, r.prompt, r.context, r.difficulty, (select id from public.categories where slug = r.cat),
            r.image, r.image_alt, 'Illustration: Pricele', 'draft', false)
    on conflict (slug) do nothing
    returning id into v_qid;

    if v_qid is not null then
      v_added := v_added + 1;
      insert into public.question_answers (question_id, answer_amount, answer_definition, reference_date, explanation)
      values (v_qid, r.amount, r.definition, r.ref_date::date, r.explanation);
      insert into public.question_sources (question_id, title, publisher, source_url, supporting_excerpt, verification_notes)
      values (v_qid, r.src_title, r.src_publisher, r.src_url, r.src_excerpt,
              concat_ws(' ', 'Researched 2026-10-18; re-check before verifying.', nullif(r.src_notes, '')));
    end if;
  end loop;
  raise notice 'Question pack pack-03: % new draft questions added', v_added;
end
$$;

select count(*) filter (where slug like any (array['pack3-costco-rotisserie-chicken', 'pack3-spotify-premium', 'pack3-airtag-2', 'pack3-powerball-ticket', 'pack3-xbox-series-x', 'pack3-galaxy-z-fold-8', 'pack3-honda-civic-2027', 'pack3-cobain-cardigan', 'pack3-titanic-door', 'pack3-thriller-jacket', 'pack3-pikachu-illustrator', 'pack3-babe-ruth-called-shot-jersey', 'pack3-t-rex-stan', 'pack3-griffin-penthouse', 'pack3-instagram-acquisition'])) as questions_in_pack
  from public.questions;
